// Replace Chirpy's old cache-first worker so deleted posts disappear after an update.
self.addEventListener('install', () => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    Promise.all([
      caches.keys().then((keys) =>
        Promise.all(keys.filter((key) => key.startsWith('chirpy-')).map((key) => caches.delete(key)))
      ),
      self.clients.claim()
    ])
  );
});
